package pages; import org.openqa.selenium.*; public class GreenKartPage {private final WebDriver d; public GreenKartPage(WebDriver d){this.d=d;} public void search(String q){d.findElement(By.cssSelector("input.search-keyword")).sendKeys(q);} public boolean productVisible(String q){return d.findElements(By.xpath("//h4[contains(translate(.,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'), '"+q.toLowerCase()+"')]")).size()>0;} public void addFirstProduct(){d.findElement(By.cssSelector("div.products div.product").concat(" button")).click();} public void openCart(){d.findElement(By.cssSelector("a.cart-icon")).click();}}